CREATE OR REPLACE FUNCTION public.enqueue_product_list(_event_key text, _message jsonb, _groups bigint[]) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE eid uuid; n bigint; BEGIN
IF auth.role() IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'Forbidden'; END IF;
IF _event_key NOT LIKE 'broadcast:product-list:%' OR _message->>'kind' IS DISTINCT FROM 'product_list' OR coalesce(_message->>'text','')='' OR octet_length(_message->>'text')>32768 OR cardinality(_groups)>100 THEN RAISE EXCEPTION 'Invalid product list'; END IF;
INSERT INTO public.stock_notification_events(event_key,kind,source,status,delivered_at,audience_message,product_snapshot) VALUES(_event_key,'broadcast','admin_product_list','delivered',now(),_message,jsonb_build_object('name','Product list broadcast')) ON CONFLICT(event_key) DO NOTHING RETURNING id INTO eid;
IF eid IS NULL THEN SELECT id INTO eid FROM public.stock_notification_events WHERE event_key=_event_key;
ELSE INSERT INTO public.stock_notification_recipients(event_id,telegram_id) SELECT eid,telegram_id FROM public.bot_users WHERE NOT is_banned AND telegram_id>0 AND contact_status NOT IN ('blocked','deactivated','stopped') ON CONFLICT DO NOTHING;
INSERT INTO public.stock_notification_recipients(event_id,telegram_id) SELECT eid,g FROM unnest(_groups) g WHERE g<0 ON CONFLICT DO NOTHING; END IF;
SELECT count(*) INTO n FROM public.stock_notification_recipients WHERE event_id=eid; RETURN jsonb_build_object('id',eid,'total',n); END $$;
REVOKE ALL ON FUNCTION public.enqueue_product_list(text,jsonb,bigint[]) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.enqueue_product_list(text,jsonb,bigint[]) TO service_role;
CREATE OR REPLACE FUNCTION public.product_list_progress(_admin_id uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE result jsonb; BEGIN
IF auth.role() IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'Forbidden'; END IF;
SELECT coalesce(jsonb_agg(to_jsonb(q)),'[]'::jsonb) INTO result FROM (SELECT e.id,e.created_at,e.audience_message->>'title' AS title,count(r.telegram_id) AS total,count(*) FILTER(WHERE r.status='sent') AS sent,count(*) FILTER(WHERE r.status IN ('unreachable','cancelled','failed')) AS failed,count(*) FILTER(WHERE r.status IN ('pending','retry','sending')) AS waiting,count(*) FILTER(WHERE r.telegram_id<0 AND r.status='sent') AS groups_sent,count(*) FILTER(WHERE r.telegram_id<0) AS groups_total FROM (SELECT * FROM public.stock_notification_events WHERE source='admin_product_list' AND audience_message->>'admin_id'=_admin_id::text ORDER BY created_at DESC LIMIT 20) e LEFT JOIN public.stock_notification_recipients r ON r.event_id=e.id GROUP BY e.id,e.created_at,e.audience_message ORDER BY e.created_at DESC) q; RETURN result; END $$;
REVOKE ALL ON FUNCTION public.product_list_progress(uuid) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.product_list_progress(uuid) TO service_role;